    X("computer-science-8-2-3", type="mcq", id="q-cs-82-pr05", stem_zh="次数事先不知道、一直做到条件不成立，较适合？", stem_en="When the number of times is not known in advance and you continue until a condition fails, a better fit is:", answer="d", exp_zh="条件循环。", exp_en="A condition-controlled loop.", options=opts(("只能使用没有退出条件的死循环", "an endless loop with no exit condition, and nothing else"), ("必须取消重复", "repetition must be cancelled"), ("只能画一个没有流程的圆", "a circle with no flow, and nothing else"), ("WHILE 这类条件循环", "a condition-controlled loop such as WHILE"))),
    X("computer-science-8-2-3", type="numeric", id="q-cs-82-pr06", stem_zh="FOR i 从 1 到 5，每次把 i 加到初值为 0 的合计，结果是多少？", stem_en="FOR i from 1 to 5, each time adding i to a total that starts at 0. What is the result?", answer=15, exp_zh="$1+2+3+4+5=15$。", exp_en="$1+2+3+4+5=15$.", tolerance=0),
    X("computer-science-8-2-1", type="mcq", id="q-cs-82-pr07", stem_zh="还没有把步骤想清楚就直接写某一种语言的细节，主要问题是？", stem_en="The main problem with writing the details of one language before the steps are clear is that:", answer="a", exp_zh="容易混乱，反而更难排错。", exp_en="The work becomes confused and harder to debug.", options=opts(("步骤容易混乱，排错也更难", "the steps become confused and debugging is harder"), ("这样一定能自动生成正确算法", "this will certainly generate a correct algorithm automatically"), ("分解会自动完成", "decomposition will finish automatically"), ("伪代码会变得不再需要任何结构", "pseudocode will no longer need any structure"))),
    X("computer-science-8-2-2", type="short", id="q-cs-82-pr08", stem_zh="流程图里，椭圆通常表示什么？", stem_en="What does an oval usually represent in a flowchart?", answer="开始或结束", accepted=["开始或结束", "起止", "start or end", "terminator", "the start or the end"], answer_zh="开始或结束。", answer_en="The start or the end.", exp_zh="这是常用约定。", exp_en="This is a common convention."),
