    X("computer-science-8-4-2", type="short", id="q-cs-84-pr08", stem_zh="写出两种常见的数据类型。", stem_en="Name two common data types.", answer="整数和字符串", accepted=["整数和字符串", "整数和布尔", "integer and string", "integer and Boolean", "float and string"], answer_zh="例如：整数和字符串。", answer_en="For example: integer and string.", exp_zh="还有布尔、小数等。", exp_en="Boolean and float are also common."),
