    X("computer-science-8-5-1", type="mcq", id="q-cs-85-pr07", stem_zh="收集午餐满意度时还要求填写家庭银行账号，问题主要在于？", stem_en="If a lunch-satisfaction survey also demands a family bank account number, the main problem is:", answer="d", exp_zh="收集了与问题无关的敏感信息。", exp_en="Sensitive information unrelated to the question is being collected.", options=opts(("银行账号能提高问卷的及时性", "the bank number improves the timeliness of the questionnaire"), ("样本会自动变得更有代表性", "the sample automatically becomes more representative"), ("这是必须的存在检查", "this is a required presence check"), ("收集了与问题无关的敏感个人信息", "sensitive personal information unrelated to the question is being collected"))),
