    X("computer-science-8-5-2", type="mcq", id="q-cs-85-pa03", stem_zh="检查必填项有没有空着，属于？", stem_en="Checking that a required field has not been left empty is:", answer="c", exp_zh="存在检查（校验）。", exp_en="A presence check (validation).", options=opts(("核对两次输入，且不管是否为空", "verification of two entries, ignoring whether they are empty"), ("硬件诊断", "a hardware diagnosis"), ("存在检查，属于校验", "a presence check, which is validation"), ("流程图起止符", "a flowchart terminator"))),
