    X("computer-science-8-6-2", type="numeric", id="q-cs-86-pr04", stem_zh="若 larger(a,b) 返回较大值，larger(9, 4) 应返回多少？", stem_en="If larger(a,b) returns the larger value, what should larger(9, 4) return?", answer=9, exp_zh="9 大于 4。", exp_en="9 is greater than 4.", tolerance=0),
